export interface FoggingEvent {
  ward_key: string;
  event_id: string;
  date: string;  // YYYY-MM-DD
  sub_area_name: string;
  gps_lat: number;
  gps_lng: number;
  personnel_designation: "Vector Team";
  team_name: string;
  supervising_mo: string;
  personnel_count: number;
  fogging_type: "cold_fogging" | "ULV";
  coverage_estimate_households: number;
  source: "KB_app" | "manual";
}

export interface FoggingStatus {
  days_since_last_fogging: number;
  fogging_status: "recent" | "due" | "overdue" | "no_record";
  expected_cadence_days: number;
  event_count_90d: number;
}

export interface BreedingSite {
  ward_key: string;
  site_id: string;
  gps_lat: number;
  gps_lng: number;
  area_name: string;
  magnitude: "major" | "minor";
  status: "open" | "resolved";
  first_reported_date: string;
  last_inspection_date: string;
  resolved_date: string | null;
  resolved_by: "source_reduction" | null;
}

export interface BreedingAggregation {
  major_open: number;
  minor_open: number;
  major_resolved: number;
  minor_resolved: number;
  days_since_last_inspection: number | null;
  total_sites_tracked: number;
}

export interface LarvalIndicesRecord {
  ward_key: string;
  week: string;  // ISO week: YYYY-Www
  week_start_date: string;
  coverage_tier: "high" | "medium" | "low" | "no_data";
  houses_inspected: number;
  houses_positive: number;
  containers_inspected: number;
  containers_positive: number;
  bi: number | null;   // Breteau Index
  hi: number | null;   // House Index (%)
  ci: number | null;   // Container Index (%)
  any_outbreak_threshold_breached: boolean;
}


