// Helper: get fogging events for a ward within a date range
export function getFoggingEventsForWard(wardKey: string, sinceDaysAgo?: number): FoggingEvent[] {
  const cutoff = sinceDaysAgo
    ? new Date(Date.now() - sinceDaysAgo * 24 * 60 * 60 * 1000)
    : null;
  return MOCK_FOGGING_EVENTS.filter(e => {
    if (e.ward_key !== wardKey) return false;
    if (!cutoff) return true;
    return new Date(e.date) >= cutoff;
  });
}

export function getFoggingStatus(wardKey: string): FoggingStatus | null {
  return FOGGING_STATUS_BY_WARD[wardKey] ?? null;
}
